1	<title>Portal Redesign — Billing</title>
2	<link rel="preconnect" href="https://fonts.googleapis.com">
3	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
4	<link href="https://fonts.googleapis.com/css2?family=Sora:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
5	
6	<style>
7	  :root{
8	    --bg:#05060d; --surface-1:#0c0f1c; --border:rgba(255,255,255,0.07); --border-strong:rgba(255,255,255,0.16);
9	    --text:#f4f5fb; --text-muted:#97a1c4; --text-faint:#5b6488;
10	    --brand:#6f47f5; --brand-light:#a48bff; --cyan:#22d3ee; --blue:#3b82f6; --good:#34d399; --warn:#fbbf24; --bad:#f87171;
11	    --font-display:"Sora","Inter",system-ui,sans-serif; --font-body:"Inter",system-ui,sans-serif;
12	  }
13	  *{ box-sizing:border-box; }
14	  body{ margin:0; background:var(--bg); color:var(--text); font-family:var(--font-body); -webkit-font-smoothing:antialiased; padding:32px 24px 64px; }
15	  .wrap{ max-width:1080px; margin:0 auto; }
16	  .tag{ display:flex; align-items:center; gap:8px; font-size:11px; font-weight:700; letter-spacing:.06em; text-transform:uppercase; color:var(--text-faint); margin-bottom:18px; }
17	  .tag .dot{ width:6px; height:6px; border-radius:999px; background:var(--brand-light); box-shadow:0 0 0 3px rgba(164,139,255,0.18); }
18	  h1{ font-family:var(--font-display); font-size:24px; font-weight:700; margin:0 0 4px; }
19	  .sub{ color:var(--text-muted); font-size:13.5px; margin:0 0 24px; }
20	
21	  /* cockpit header */
22	  .cockpit{ background:var(--surface-1); border:1px solid var(--border); border-radius:20px; padding:24px; margin-bottom:20px; display:grid; grid-template-columns:1fr 1fr 200px; gap:24px; align-items:center; }
23	  @media (max-width:760px){ .cockpit{ grid-template-columns:1fr; } }
24	  .cockpit-metric .lbl{ font-size:11.5px; color:var(--text-faint); margin-bottom:6px; }
25	  .cockpit-metric .val{ font-family:var(--font-display); font-size:26px; font-weight:800; }
26	  .cockpit-metric .note{ font-size:11.5px; color:var(--good); margin-top:4px; }
27	  .gauge-wrap{ display:flex; justify-content:center; }
28	
29	  .alert-banner{ display:flex; align-items:center; gap:12px; background:rgba(251,191,36,0.1); border:1px solid rgba(251,191,36,0.3); border-radius:16px; padding:14px 18px; margin-bottom:20px; }
30	  .alert-banner svg{ width:19px; height:19px; color:var(--warn); flex-shrink:0; }
31	  .alert-banner .t1{ font-size:13px; font-weight:600; }
32	  .alert-banner .t2{ font-size:12px; color:var(--text-muted); }
33	  .alert-banner .act{ margin-left:auto; background:rgba(255,255,255,0.08); border:1px solid var(--border-strong); color:var(--text); font-size:12px; font-weight:600; border-radius:9px; padding:8px 14px; cursor:pointer; white-space:nowrap; }
34	
35	  .tabs{ display:flex; gap:6px; margin-bottom:20px; border-bottom:1px solid var(--border); }
36	  .tab{ padding:11px 16px; font-size:13px; font-weight:600; color:var(--text-faint); cursor:pointer; border-bottom:2px solid transparent; margin-bottom:-1px; }
37	  .tab.active{ color:var(--text); border-bottom-color:var(--brand-light); }
38	
39	  .tabpanel{ display:none; }
40	  .tabpanel.active{ display:block; }
41	
42	  .grid2{ display:grid; grid-template-columns:1fr 1fr; gap:16px; }
43	  @media (max-width:760px){ .grid2{ grid-template-columns:1fr; } }
44	  .panel{ background:var(--surface-1); border:1px solid var(--border); border-radius:18px; padding:20px 22px; margin-bottom:16px; }
45	  .panel-title{ font-family:var(--font-display); font-size:14px; font-weight:700; margin-bottom:14px; }
46	
47	  .pm-row{ display:flex; align-items:center; gap:12px; padding:12px; border:1px solid var(--border); border-radius:13px; }
48	  .pm-icon{ width:38px; height:26px; border-radius:5px; background:linear-gradient(135deg,#4c5fd6,#8b5cf6); display:flex; align-items:center; justify-content:center; font-size:9px; font-weight:800; color:#fff; }
49	  .pm-num{ font-size:13px; font-weight:600; }
50	  .pm-exp{ font-size:11px; color:var(--text-faint); }
51	  .pm-edit{ margin-left:auto; font-size:12px; color:var(--brand-light); font-weight:600; cursor:pointer; }
52	
53	  .toggle-row{ display:flex; align-items:center; justify-content:space-between; padding:11px 0; border-bottom:1px solid var(--border); }
54	  .toggle-row:last-child{ border-bottom:none; }
55	  .tr-label{ font-size:13px; font-weight:600; }
56	  .tr-note{ font-size:11.5px; color:var(--text-faint); margin-top:2px; }
57	  .switch{ width:38px; height:22px; border-radius:999px; background:rgba(255,255,255,0.1); position:relative; cursor:pointer; flex-shrink:0; }
58	  .switch.on{ background:var(--brand); }
59	  .switch::after{ content:""; position:absolute; top:2px; left:2px; width:18px; height:18px; border-radius:999px; background:#fff; transition:left .15s ease; }
60	  .switch.on::after{ left:18px; }
61	
62	  .txn-row{ display:flex; align-items:center; gap:12px; padding:11px 0; border-bottom:1px solid var(--border); font-size:12.5px; }
63	  .txn-row:last-child{ border-bottom:none; }
64	  .txn-icon{ width:30px; height:30px; border-radius:9px; background:rgba(255,255,255,0.04); border:1px solid var(--border); display:flex; align-items:center; justify-content:center; flex-shrink:0; }
65	  .txn-icon svg{ width:14px; height:14px; color:var(--text-muted); }
66	  .txn-desc{ font-weight:600; }
67	  .txn-date{ color:var(--text-faint); font-size:11.5px; }
68	  .txn-amt{ margin-left:auto; font-weight:700; }
69	  .txn-amt.neg{ color:var(--bad); } .txn-amt.pos{ color:var(--good); }
70	  .txn-dl{ color:var(--text-faint); cursor:pointer; width:15px; height:15px; }
71	
72	  .slider-row{ margin:8px 0 4px; }
73	  .slider-row input{ width:100%; }
74	  .slider-labels{ display:flex; justify-content:space-between; font-size:11px; color:var(--text-faint); }
75	</style>
76	
77	<div class="wrap">
78	  <div class="tag"><span class="dot"></span>Concept mockup — redesigned billing, not wired to real account data</div>
79	  <h1>Billing</h1>
80	  <p class="sub">Your balance, spend, and payment settings — organized so what needs attention is the first thing you see.</p>
81	
82	  <div class="alert-banner">
83	    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 9v4M12 17h.01"/><path d="M10.3 3.9 2.4 18a1.8 1.8 0 0 0 1.5 2.7h16.2a1.8 1.8 0 0 0 1.5-2.7L13.7 3.9a1.8 1.8 0 0 0-3.4 0Z"/></svg>
84	    <div><div class="t1">Your balance won't cover next month's renewals</div><div class="t2">Estimated shortfall: $14.20 on Oct 3</div></div>
85	    <button class="act">Add funds</button>
86	  </div>
87	
88	  <div class="cockpit">
89	    <div class="cockpit-metric">
90	      <div class="lbl">Wallet balance</div>
91	      <div class="val">$247.10</div>
92	      <div class="note">Covers ~18 days at current spend</div>
93	    </div>
94	    <div class="cockpit-metric">
95	      <div class="lbl">Spend this month</div>
96	      <div class="val">$13.20</div>
97	      <div class="note" style="color:var(--text-faint)">vs $18.40 last month</div>
98	    </div>
99	    <div class="gauge-wrap"><svg width="140" height="90" viewBox="0 0 140 90"><path d="M10 80 A60 60 0 0 1 130 80" fill="none" stroke="rgba(255,255,255,0.08)" stroke-width="10" stroke-linecap="round"/><path id="gaugeArc" d="M10 80 A60 60 0 0 1 130 80" fill="none" stroke="url(#gg)" stroke-width="10" stroke-linecap="round" stroke-dasharray="188" stroke-dashoffset="47"/><defs><linearGradient id="gg" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stop-color="#a48bff"/><stop offset="100%" stop-color="#22d3ee"/></linearGradient></defs><text x="70" y="72" text-anchor="middle" fill="#f4f5fb" font-family="Sora" font-weight="700" font-size="18">75%</text></svg></div>
100	  </div>
101	
102	  <div class="tabs">
103	    <div class="tab active" data-tab="overview">Overview</div>
104	    <div class="tab" data-tab="payment">Payment & auto-recharge</div>
105	    <div class="tab" data-tab="spend">Spend controls</div>
106	    <div class="tab" data-tab="txns">Transactions & invoices</div>
107	  </div>
108	
109	  <div class="tabpanel active" data-panel="overview">
110	    <div class="grid2">
111	      <div class="panel">
112	        <div class="panel-title">Upcoming renewals</div>
113	        <div class="txn-row"><div class="txn-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="6" rx="1.6"/><rect x="3" y="14" width="18" height="6" rx="1.6"/></svg></div><div><div class="txn-desc">rust-w75hko</div><div class="txn-date">Renews Oct 3</div></div><div class="txn-amt">$12.99</div></div>
114	        <div class="txn-row"><div class="txn-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18"/></svg></div><div><div class="txn-desc">nxplay.gg</div><div class="txn-date">Renews Oct 14</div></div><div class="txn-amt">$14.41</div></div>
115	      </div>
116	      <div class="panel">
117	        <div class="panel-title">Quick links</div>
118	        <div class="toggle-row"><div><div class="tr-label">Redeem a code</div><div class="tr-note">Gift card or promo credit</div></div><span style="color:var(--brand-light);font-size:12px;font-weight:600;cursor:pointer">Redeem →</span></div>
119	        <div class="toggle-row"><div><div class="tr-label">Download this year's invoices</div></div><span style="color:var(--brand-light);font-size:12px;font-weight:600;cursor:pointer">Export →</span></div>
120	      </div>
121	    </div>
122	  </div>
123	
124	  <div class="tabpanel" data-panel="payment">
125	    <div class="panel">
126	      <div class="panel-title">Payment method</div>
127	      <div class="pm-row"><div class="pm-icon">VISA</div><div><div class="pm-num">•••• 5305</div><div class="pm-exp">Expires 08/28</div></div><div class="pm-edit">Update</div></div>
128	    </div>
129	    <div class="panel">
130	      <div class="panel-title">Auto-recharge</div>
131	      <div class="toggle-row"><div><div class="tr-label">Automatically add funds</div><div class="tr-note">When balance drops below $10, add $25</div></div><div class="switch on"></div></div>
132	    </div>
133	  </div>
134	
135	  <div class="tabpanel" data-panel="spend">
136	    <div class="panel">
137	      <div class="panel-title">Monthly spend cap</div>
138	      <div class="slider-row"><input type="range" min="0" max="500" value="150"></div>
139	      <div class="slider-labels"><span>$0</span><span>Cap: $150/mo</span><span>$500</span></div>
140	    </div>
141	    <div class="panel">
142	      <div class="toggle-row"><div><div class="tr-label">Email me at 80% of cap</div></div><div class="switch on"></div></div>
143	      <div class="toggle-row"><div><div class="tr-label">Pause new deploys at 100% of cap</div></div><div class="switch"></div></div>
144	    </div>
145	  </div>
146	
147	  <div class="tabpanel" data-panel="txns">
148	    <div class="panel">
149	      <div class="panel-title">Recent transactions</div>
150	      <div class="txn-row"><div class="txn-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="6" width="18" height="13" rx="2.4"/></svg></div><div><div class="txn-desc">Auto-recharge</div><div class="txn-date">Sep 30</div></div><div class="txn-amt pos">+$25.00</div><svg class="txn-dl" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 4v12m0 0 4-4m-4 4-4-4M4 20h16"/></svg></div>
151	      <div class="txn-row"><div class="txn-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="6" rx="1.6"/></svg></div><div><div class="txn-desc">rust-w75hko renewal</div><div class="txn-date">Sep 3</div></div><div class="txn-amt neg">-$12.99</div><svg class="txn-dl" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 4v12m0 0 4-4m-4 4-4-4M4 20h16"/></svg></div>
152	      <div class="txn-row"><div class="txn-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/></svg></div><div><div class="txn-desc">nxplay.gg registration</div><div class="txn-date">Aug 14</div></div><div class="txn-amt neg">-$14.41</div><svg class="txn-dl" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 4v12m0 0 4-4m-4 4-4-4M4 20h16"/></svg></div>
153	    </div>
154	  </div>
155	</div>
156	
157	<script>
158	  document.querySelectorAll('.tab').forEach(el => {
159	    el.addEventListener('click', () => {
160	      document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
161	      document.querySelectorAll('.tabpanel').forEach(p => p.classList.remove('active'));
162	      el.classList.add('active');
163	      document.querySelector(`.tabpanel[data-panel="${el.dataset.tab}"]`).classList.add('active');
164	    });
165	  });
166	  document.querySelectorAll('.switch').forEach(el => el.addEventListener('click', () => el.classList.toggle('on')));
167	</script>
