1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { canAccess } from "@/lib/rbac";
5	import { timeAgo } from "@/components/ui/primitives";
6	import { PortalHero } from "@/components/portal/PortalHero";
7	import {
8	  ProfileForm,
9	  PasswordForm,
10	  AddSshKeyForm,
11	  DeleteSshKeyButton,
12	} from "@/components/customer/SettingsForms";
13	import { SecuritySettings } from "@/components/customer/SecuritySettings";
14	import { NotificationPrefs } from "@/components/customer/NotificationPrefs";
15	import { DangerZone } from "@/components/customer/DangerZone";
16	import { CloudflareIntegration } from "@/components/customer/CloudflareIntegration";
17	import { ClaudeKeyConnect } from "@/components/customer/ClaudeKeyConnect";
18	import { DiscordIntegration } from "@/components/admin/DiscordIntegration";
19	import { SignOutOthersButton } from "@/components/customer/AccountSecurityExtras";
20	import { normalizePrefs } from "@/lib/prefs";
21	import { getCloudflareStatus, cloudflareRedirectUri } from "@/lib/actions-cloudflare";
22	import { getDiscordLinkStatus } from "@/lib/actions-discord-link";
23	
24	export const dynamic = "force-dynamic";
25	
26	// Settings is organised into sub-tabs (server-rendered via ?tab=). "Integrations"
27	// groups the third-party connections — the customer's Anthropic (Claude) key and
28	// their Cloudflare connection — so credentials live in one obvious place.
29	const TABS = [
30	  { id: "profile", label: "Profile" },
31	  { id: "security", label: "Security" },
32	  { id: "integrations", label: "Integrations" },
33	  { id: "notifications", label: "Notifications" },
34	] as const;
35	type TabId = (typeof TABS)[number]["id"];
36	
37	function shortKey(publicKey: string): string {
38	  const parts = publicKey.trim().split(/\s+/);
39	  const body = parts[1] ?? parts[0] ?? "";
40	  const type = parts[0] ?? "";
41	  if (body.length <= 40) return publicKey;
42	  return `${type} ${body.slice(0, 24)}…${body.slice(-12)}`;
43	}
44	
45	export default async function SettingsPage({
46	  searchParams,
47	}: {
48	  searchParams: Promise<{ tab?: string }>;
49	}) {
50	  const user = await requireUser();
51	  const { tab: rawTab } = await searchParams;
52	  const tab: TabId = (TABS.some((t) => t.id === rawTab) ? rawTab : "profile") as TabId;
53	
54	  const sshKeys = await db.sshKey.findMany({
55	    where: { userId: user.id },
56	    orderBy: { createdAt: "desc" },
57	  });
58	  const apiTokens = await db.apiToken.findMany({
59	    where: { userId: user.id },
60	    orderBy: { createdAt: "desc" },
61	    select: {
62	      id: true,
63	      name: true,
64	      prefix: true,
65	      scopes: true,
66	      lastUsedAt: true,
67	      expiresAt: true,
68	      revoked: true,
69	      createdAt: true,
70	    },
71	  });
72	  const prefs = normalizePrefs(user.notificationPrefs);
73	  // Discord account linking is a support-staff feature (it exists purely to
74	  // attribute Discord-bridge replies — see lib/discord-bridge.ts's
75	  // `resolveDiscordReplyActor`, which itself gates on `canAccess(role,
76	  // "support")`), so only fetch/show it for roles that could ever use it. A
77	  // CUSTOMER or BILLING-only account would otherwise see a "Connect Discord"
78	  // button that can never do anything for them.
79	  const canUseDiscordBridge = canAccess(user.role, "support");
80	  const [cloudflare, cfRedirectUri, discord] = await Promise.all([
81	    getCloudflareStatus(),
82	    cloudflareRedirectUri(),
83	    canUseDiscordBridge ? getDiscordLinkStatus() : Promise.resolve(null),
84	  ]);
85	
86	  return (
87	    <div className="space-y-6">
88	      <PortalHero variant="settings" title="Settings" sub="Profile, security, integrations and access credentials." />
89	
90	      <div className="flex flex-wrap gap-1 border-b border-white/10">
91	        {TABS.map((t) => (
92	          <Link
93	            key={t.id}
94	            href={`/dashboard/settings?tab=${t.id}`}
95	            className={`-mb-px rounded-t-lg border-b-2 px-4 py-2 text-sm font-medium transition ${
96	              tab === t.id
97	                ? "border-brand-500 text-white"
98	                : "border-transparent text-slate-400 hover:text-slate-200"
99	            }`}
100	          >
101	            {t.label}
102	          </Link>
103	        ))}
104	      </div>
105	
106	      {tab === "profile" && (
107	        <>
108	          <div className="card">
109	            <h2 className="mb-4 font-semibold">Account overview</h2>
110	            <dl className="grid gap-4 sm:grid-cols-3">
111	              <div>
112	                <dt className="text-xs uppercase tracking-wide text-slate-500">Member since</dt>
113	                <dd className="mt-1 text-sm font-medium">
114	                  {user.createdAt.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" })}
115	                </dd>
116	              </div>
117	              <div>
118	                <dt className="text-xs uppercase tracking-wide text-slate-500">Email</dt>
119	                <dd className="mt-1 text-sm font-medium">
120	                  {user.emailVerifiedAt ? (
121	                    <span className="text-emerald-400">Verified</span>
122	                  ) : (
123	                    <span className="text-amber-400">Unverified</span>
124	                  )}
125	                </dd>
126	              </div>
127	              <div>
128	                <dt className="text-xs uppercase tracking-wide text-slate-500">Wallet balance</dt>
129	                <dd className="mt-1 text-sm font-medium tabular-nums">${(user.balanceCents / 100).toFixed(2)}</dd>
130	              </div>
131	            </dl>
132	          </div>
133	
134	          <div className="card">
135	            <h2 className="mb-4 font-semibold">Profile</h2>
136	            <ProfileForm name={user.name} email={user.email} />
137	          </div>
138	
139	          <div className="card">
140	            <h2 className="mb-4 font-semibold">Password</h2>
141	            <PasswordForm />
142	          </div>
143	
144	          <div className="card">
145	            <div className="mb-1 flex items-center justify-between">
146	              <h2 className="font-semibold">SSH keys</h2>
147	              <span className="text-xs text-slate-500">
148	                {sshKeys.length} key{sshKeys.length === 1 ? "" : "s"}
149	              </span>
150	            </div>
151	            <p className="mb-5 text-sm text-slate-400">
152	              Keys are injected into new servers automatically at deploy time.
153	            </p>
154	
155	            {sshKeys.length > 0 && (
156	              <ul className="mb-6 divide-y divide-white/[0.05] rounded-xl border border-white/[0.06]">
157	                {sshKeys.map((k) => (
158	                  <li key={k.id} className="flex items-center justify-between gap-4 px-4 py-3">
159	                    <div className="min-w-0">
160	                      <p className="text-sm font-medium">{k.name}</p>
161	                      <p className="truncate font-mono text-xs text-slate-500">{shortKey(k.publicKey)}</p>
162	                    </div>
163	                    <div className="flex shrink-0 items-center gap-3">
164	                      <span className="hidden text-xs text-slate-500 sm:block">
165	                        added {timeAgo(k.createdAt)}
166	                      </span>
167	                      <DeleteSshKeyButton keyId={k.id} />
168	                    </div>
169	                  </li>
170	                ))}
171	              </ul>
172	            )}
173	
174	            <AddSshKeyForm />
175	          </div>
176	
177	          <DangerZone email={user.email} />
178	        </>
179	      )}
180	
181	      {tab === "security" && (
182	        <>
183	          <SecuritySettings totpEnabled={user.totpEnabled} tokens={apiTokens} />
184	          <SignOutOthersButton />
185	        </>
186	      )}
187	
188	      {tab === "integrations" && (
189	        <>
190	          <CloudflareIntegration
191	            connected={cloudflare.connected}
192	            kind={cloudflare.kind}
193	            oauthAvailable={cloudflare.oauthAvailable}
194	            scopeSummary={cloudflare.scopeSummary}
195	            redirectUri={cfRedirectUri}
196	          />
197	
198	          {/* BYOK — the customer's own Anthropic key. Deep-linked from Build with AI
199	              as /dashboard/settings?tab=integrations#anthropic-key; keep the id stable. */}
