156	/* ── Gauge (semicircular, billing mockup) ────────────────────────────── */
157	
158	/**
159	 * Hand-rolled semicircular gauge — billing mockup's wallet-usage arc.
160	 * Geometry matches the mockup exactly: a 140x90 viewBox, radius-60 arc from
161	 * (10,80) to (130,80). That arc's true length is `π * r ≈ 188.5`, which is
162	 * where the mockup's hardcoded `stroke-dasharray="188"` came from — computed
163	 * here instead of hardcoded so `value` can be any 0-100, not just the
164	 * mockup's fixed 75%.
165	 */
166	export function Gauge({ value, size = 140 }: { value: number; size?: number }) {
167	  const pct = Math.max(0, Math.min(100, value));
168	  const height = size * (90 / 140);
169	  const arcLength = Math.PI * 60;
170	  const offset = arcLength * (1 - pct / 100);
171	  const gradientId = "pv-gauge-grad";
172	  return (
173	    <svg width={size} height={height} viewBox="0 0 140 90">
174	      <path d="M10 80 A60 60 0 0 1 130 80" fill="none" stroke="rgb(255 255 255 / 0.08)" strokeWidth="10" strokeLinecap="round" />
175	      <path
176	        d="M10 80 A60 60 0 0 1 130 80"
177	        fill="none"
178	        stroke={`url(#${gradientId})`}
179	        strokeWidth="10"
180	        strokeLinecap="round"
181	        strokeDasharray={arcLength}
182	        strokeDashoffset={offset}
183	        style={{ transition: "stroke-dashoffset 0.6s cubic-bezier(0.22,1,0.36,1)" }}
184	      />
185	      <defs>
186	        <linearGradient id={gradientId} x1="0" y1="0" x2="1" y2="0">
187	          <stop offset="0%" stopColor="#a48bff" />
188	          <stop offset="100%" stopColor="#22d3ee" />
189	        </linearGradient>
190	      </defs>
191	      <text
192	        x="70"
193	        y="72"
194	        textAnchor="middle"
195	        fill="#f4f5fb"
196	        fontFamily="var(--font-pv-display)"
197	        fontWeight={700}
198	        fontSize="18"
199	      >
200	        {Math.round(pct)}%
201	      </text>
202	    </svg>
203	  );
204	}
205	
206	/* ── BarMeter (linear, server-detail mockup) ─────────────────────────── */
207	
208	/**
209	 * Linear usage bar — server-detail mockup's CPU/Memory/Disk meters.
210	 * `tone="warn"` reproduces the mockup's disk-at-76%-amber-to-red treatment;
211	 * use it once a metric crosses whatever threshold the calling page defines
212	 * (the mockup didn't encode a fixed rule — it's a per-page call).
213	 */
214	export function BarMeter({
215	  value,
216	  max = 100,
217	  tone = "brand",
218	}: {
219	  value: number;
220	  max?: number;
221	  tone?: "brand" | "warn";
222	}) {
223	  const pct = Math.max(0, Math.min(100, (value / max) * 100));
224	  return (
225	    <div className="h-1.5 overflow-hidden rounded-full bg-white/[0.06]">
226	      <div
227	        className="h-full rounded-full"
228	        style={{
229	          width: `${pct}%`,
230	          background:
231	            tone === "warn"
232	              ? "linear-gradient(90deg, #fbbf24, #f87171)"
233	              : "linear-gradient(90deg, #a48bff, #22d3ee)",
234	          transition: "width 0.5s cubic-bezier(0.22,1,0.36,1)",
235	        }}
236	      />
237	    </div>
238	  );
239	}
