import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { annualDiscountPct } from "@/lib/annual-discount";
import { DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
import { getSettingBool, getSettingInt } from "@/lib/settings";
import { taxContextForUser } from "@/lib/tax";
import { Surface, IconTile, Pill, StatusPill, Gauge, BarMeter } from "@/components/portal-v2/primitives";
import { IconAlert, IconCheck, IconWallet, IconChart, IconServers, IconShieldCheck } from "@/components/portal-v2/icons";

export const dynamic = "force-dynamic";

// Billing is organised into sub-tabs (server-rendered via ?tab=), the same
// convention app/dashboard/settings/page.tsx uses. The wallet cockpit and any
// overdue/shortfall banner render ABOVE the tab bar — on every tab, not just
// Overview — so the one thing that actually needs attention is never a click
// away, matching scratchpad/portal-redesign-billing.html's DOM order (the
// alert banner and cockpit sit outside its .tabpanel elements).
const TABS = [
  { id: "overview", label: "Overview" },
  { id: "payment", label: "Payment & auto-recharge" },
  { id: "spend", label: "Spend controls" },
  { id: "transactions", label: "Transactions & invoices" },
] as const;
type TabId = (typeof TABS)[number]["id"];

export default async function BillingPage({
  searchParams,
}: {
  searchParams: Promise<{ tab?: string; paid?: string; canceled?: string; card_setup?: string }>;
}) {
  const { tab: rawTab, paid, canceled, card_setup: cardSetup } = await searchParams;
  const tab: TabId = (TABS.some((t) => t.id === rawTab) ? rawTab : "overview") as TabId;
  const user = await requireUser();
  // Resolved once for the whole page so every row formats identically.
  const invoiceNumberPrefix = (await invoiceBranding()).numberPrefix;
  const [transactions, paidServers, bwServers, invoices] = await Promise.all([
    db.walletTransaction.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 60,
    }),
    db.server.findMany({
      where: { userId: user.id, isFree: false, status: { not: "DELETING" } },
      // `gamePlan` and `dedicatedIp` are what `renewalCharge` needs to price a
      // renewal correctly. Without them this page could only reach for
      // `plan.priceCents`, which is a different number — see the renewals block
      // below for the incident.
      include: { plan: true, gamePlan: true, dedicatedIp: true },
      orderBy: { expiresAt: "asc" },
    }),
    db.server.findMany({
      where: { userId: user.id, status: { not: "DELETING" } },
      include: { plan: true },
      orderBy: { createdAt: "asc" },
    }),
    db.invoice.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 5,
    }),
  ]);

  /* ---------------- Card on file + anything overdue ---------------- */

  // An admin impersonating a customer must not be able to attach, remove or use a
  // card on their account — `assertNotImpersonating` refuses these actions server
  // side, so the controls are hidden rather than left to throw when clicked.
  const isImpersonating = (await impersonating()) !== null;
  const cardOnFile = hasChargeableCard(user);
  const cardLabel = cardDisplayLabel({
    brand: user.cardBrand,
    last4: user.cardLast4,
    expMonth: user.cardExpMonth,
    expYear: user.cardExpYear,
  });

  // The saved card's own health. `cardExpiresAt` returns the first instant the card
  // is no longer valid — a card works THROUGH the last day of its expiry month.
  const now = new Date();
  const cardExpiry =
    user.cardExpMonth && user.cardExpYear
      ? cardExpiresAt(user.cardExpMonth, user.cardExpYear)
      : null;
  const cardExpired = cardExpiry !== null && cardExpiry <= now;
  const cardExpiringSoon =
    cardExpiry !== null &&
    !cardExpired &&
    cardExpiry.getTime() - now.getTime() <= CARD_EXPIRY_WARN_DAYS * 86_400_000;

  // Servers the renewal sweep is actively collecting for. The status filter is the
  // same one `dueServers` in worker/billing.ts uses, so this panel can never claim
  // a retry is coming for a server the sweep does not look at. SUSPENDED servers
  // are handled separately below — the sweep skips those entirely.
  const overdueServers = await db.server.findMany({
    where: {
      userId: user.id,
      isFree: false,
      expiresAt: { lt: now },
      status: { in: ["RUNNING", "STOPPED"] },
    },
    include: { plan: true, gamePlan: true, dedicatedIp: true },
    orderBy: { expiresAt: "asc" },
  });
  const suspendedUnpaid = await db.server.findMany({
    where: { userId: user.id, status: "SUSPENDED", suspendReason: "UNPAID" },
    orderBy: { expiresAt: "asc" },
  });

  // Prices and dunning windows are read exactly as the worker reads them, so the
  // amount quoted here is the amount the sweep will actually try to take.
  const graceDays = Math.max(
    0,
    await getSettingInt("dunning_grace_days", Number(process.env.NXEON_GRACE_DAYS ?? 3)),
  );
  const autoSuspend = await getSettingBool("auto_suspend_enabled", true);
  // VAT/GST for this customer (Finding 1) so every renewal figure on this page is
  // tax-inclusive and equals what the sweep / Renew now / settle-outstanding charge.
  const taxRatePercent = (await taxContextForUser(user)).ratePercent;
  const prices =
    paidServers.length > 0
      ? {
          ipMonthlyCents: await dedicatedIpMonthlyCents(),
          extraDiskPerGbCents: await extraDiskPerGbCents(),
          backupPlusCents: await backupPlusMonthlyCents(),
          annualDiscountPct: await annualDiscountPct(),
          taxRatePercent,
        }
      // No paid servers -> renewalCharge is never called; the shipped default just
      // satisfies the required field.
      : { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: DEFAULT_ANNUAL_DISCOUNT_PCT, taxRatePercent };

  // EVERY recurring figure on this page is priced through `renewalCharge` — the
  // one function worker/billing.ts sweeps with, the saved-card path charges
  // through, and the "Renew now" button quotes from (lib/renewal-quote.ts).
  //
  // "Upcoming renewals" used to print `plan.priceCents` beside a renewal DATE.
  // That is not the amount that comes out on that date: on an annual Starter it
  // read $8.99 next to the day the sweep takes $97.09, and on a game server it
  // read the base VPS plan's $8.99 for a product sold at $4.99. It is the same
  // defect as the "Renew now (+30 days, $8.99)" button that took $97.09 — a
  // SECOND price formula, not a wrong one. There is one, and it lives in
  // lib/renewal-charge.ts.
  const renewals = paidServers.map((s) => ({ server: s, charge: renewalCharge(s, prices) }));
  // Monthly run-rate. Deliberately a division of the AUTHORITATIVE term total
  // rather than a fresh sum of `plan.priceCents`: an annual server's monthly
  // share is its real term price spread over the months it buys, and a game
  // server contributes its game-plan price, not the VPS plan it is built on.
  const monthlySpendCents = renewals.reduce(
    (sum, r) => sum + Math.round(r.charge.totalCents / Math.max(1, r.charge.months)),
    0,
  );
  const upcoming = renewals.filter((r) => r.server.expiresAt !== null);

  // One quote per overdue server, built from the SAME `renewalCharge` + `walletSplit`
  // pair that `settleOutstanding` and the sweep use. The three must never disagree:
  // a page that quotes a different total than the charge that follows is the exact
  // failure both of those call sites carry a comment about.
  const overdue = overdueServers.map((s) => {
    const charge = renewalCharge(s, prices);
    const split = walletSplit({
      dueCents: charge.totalCents,
      balanceCents: user.balanceCents,
      useWallet: true,
    });
    return {
      server: s,
      charge,
      split,
      view: dunningView(s, { hasCard: cardOnFile, graceDays, autoSuspend, now }),
    };
  });
  const totalOutstandingCents = overdue.reduce((sum, o) => sum + o.charge.totalCents, 0);
  // A server can be past its expiry date and still fully funded — the sweep runs every
  // ten minutes, so "overdue" and "short of money" are different things. Only the
  // second one is an emergency, and only it gets the red treatment.
  const anyShortfall = overdue.some((o) => o.split.cardCents > 0);
  // "The card failed" is not a column — `dunningStage` counts card attempts that
  // have FAILED for the current unpaid period, so a stage above zero while a card is
  // on file IS the saved card having been declined. Anything less specific here
  // would be guessing.
  const cardDeclined = cardOnFile && overdue.some((o) => o.view.inDunning);
  const fmtDay = (d: Date) =>
    d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
  // Widened from its literal type on purpose: the copy below pluralises off this
  // number, and TypeScript rejects `=== 1` as impossible against the literal `3` —
  // which would leave the sentence unable to survive a change to the ladder.
  const retryAttempts: number = DUNNING_RETRY_ATTEMPTS;
  // "1, 3 and 5" — built from the real ladder rather than written out, so a change to
  // DUNNING_RETRY_ATTEMPTS reads correctly here instead of silently going stale.
  const retryDayList =
    RETRY_DAYS.length === 1
      ? String(RETRY_DAYS[0])
      : `${RETRY_DAYS.slice(0, -1).join(", ")} and ${RETRY_DAYS[RETRY_DAYS.length - 1]}`;

  // Bandwidth usage: metered transfer (bwIn + bwOut, written by the worker's
  // metering sweep) vs plan allowance (bandwidthTB * 1e12 bytes).
  //
  // This panel used to divide the raw columns by the allowance and print the
  // result. Nothing wrote those columns, so it read a permanent "0 B / 20 TB ·
  // 0%" under the title "Transfer used this cycle" — a figure that looked
  // authoritative and was pure fiction. Everything shown now goes through
  // bwUsageView, which reports the period the meter ACTUALLY covers and
  // withholds the percentage entirely until a sample exists.
  const bwHealth = await readBwMeterHealth();
  const bandwidth = bwServers.map((s) => ({
    server: s,
    view: bwUsageView(s, s.plan.bandwidthTB * 1e12, bwHealth),
  }));
  const bwMeasured = bwHealth.startedAt !== null;
  const totalUsedBytes = bandwidth.reduce((sum, b) => sum + b.view.usedBytes, 0);
  const totalAllowanceBytes = bandwidth.reduce((sum, b) => sum + b.view.allowanceBytes, 0);
  const totalPct = totalAllowanceBytes > 0 ? (totalUsedBytes / totalAllowanceBytes) * 100 : 0;
  const bwPartial = bandwidth.some((b) => b.view.partial);
  const bwGap = bandwidth.some((b) => b.view.hasGap);
  const meterColor = (pct: number) => (pct > 100 ? "#ef4444" : pct > 80 ? "#f59e0b" : "#6f47f5");
  const pctTone = (pct: number) =>
    pct > 100 ? "text-red-400" : pct > 80 ? "text-amber-400" : "text-slate-400";

  // Spend cap usage, read once here (moved out of an inline JSX `await` — same
  // value, computed up front like everything else on this page).
  const spentThisMonthCents = await monthSpendCents(user.id);

  /* ---------------- Cockpit header (balance / spend-rate / next charge) ---- */
  // The gauge is a "balance health" read: what share of a full month's run-rate
  // the current balance would cover, capped at 100%. An account with no
  // recurring spend yet (no paid servers) reads as fully covered rather than
  // dividing by zero.
  const balanceCoveragePct =
    monthlySpendCents > 0 ? Math.min(100, (user.balanceCents / monthlySpendCents) * 100) : 100;
  const daysOfRunway =
    monthlySpendCents > 0 ? Math.round((user.balanceCents / monthlySpendCents) * 30) : null;
  // Same ordering `upcoming` already renders in (paidServers is queried
  // `orderBy expiresAt asc`), so "next" here is exactly the first row of the
  // Upcoming renewals panel below.
  const nextRenewal = upcoming[0] ?? null;

  const tabHref = (id: TabId) => `/dashboard/billing?tab=${id}`;

  return (
    <div className="space-y-6">
      <PortalHero variant="billing" title="Billing" sub="Wallet, renewals and transaction history." />

      {paid === "1" && (
        <Surface className="flex items-center gap-3 border-pv-good/30 !bg-pv-good/[0.06] p-4 text-sm text-pv-good">
          <IconTile tone="green"><IconCheck width={16} height={16} /></IconTile>
          Payment received — your balance updates within seconds. Refresh if you don&apos;t see it
          yet.
        </Surface>
      )}
      {canceled === "1" && (
        <Surface className="flex items-center gap-3 border-pv-warn/30 !bg-pv-warn/[0.06] p-4 text-sm text-pv-warn">
          <IconTile tone="violet"><IconAlert width={16} height={16} /></IconTile>
          Checkout canceled — no charge was made.
        </Surface>
      )}

      {/* The return leg from Stripe's hosted setup page. Stripe attaches the card
          to the customer BEFORE redirecting here, so this has to run and has to
          report what happened — see CardSetupReturn. */}
      {cardSetup && <CardSetupReturn sessionId={cardSetup} />}

      {/* Nothing else on this page matters while a server is overdue, so it goes
          first — above the wallet, above the tabs, above everything, on every
          tab. Restyled onto the portal-v2 Surface/StatusPill/Pill language but
          every figure and every branch below is unchanged. */}
      {overdue.length > 0 && (
        <Surface
          className={`p-5 ${anyShortfall ? "border-pv-bad/30 !bg-pv-bad/[0.05]" : "border-pv-warn/30 !bg-pv-warn/[0.05]"}`}
        >
          <div className="flex flex-wrap items-start justify-between gap-4">
            <div className="flex items-start gap-3">
              <IconTile tone={anyShortfall ? "violet" : "violet"}>
                <IconAlert width={17} height={17} className={anyShortfall ? "text-pv-bad" : "text-pv-warn"} />
              </IconTile>
              <div>
                <div className="flex flex-wrap items-center gap-2">
                  <StatusPill tone={anyShortfall ? "bad" : "warn"}>
                    {anyShortfall ? "Action needed" : "Renewing shortly"}
                  </StatusPill>
                  <Pill tone={anyShortfall ? "bad" : "warn"}>
                    {overdue.length} overdue renewal{overdue.length === 1 ? "" : "s"}
                  </Pill>
                </div>
                <p className="mt-2 text-sm text-pv-text-muted">
                  {!anyShortfall
                    ? "Your wallet covers these — they complete automatically within a few minutes, with nothing for you to do."
                    : cardOnFile
                      ? cardDeclined
                        ? `We tried ${cardLabel ?? "your saved card"} and it was declined. Nothing is suspended yet.`
                        : `We'll charge ${cardLabel ?? "your saved card"} for anything your wallet doesn't cover.`
                      : "These can only be paid from your wallet balance, and it doesn't cover them."}
                </p>
              </div>
            </div>
            <div className="text-right">
              <p className="text-xs text-pv-text-faint">Total outstanding</p>
              <p className={`font-pv-display text-2xl font-bold ${anyShortfall ? "text-pv-bad" : "text-pv-warn"}`}>
                {fmtMoney(totalOutstandingCents)}
              </p>
            </div>
          </div>

          <ul className="mt-5 space-y-4">
            {overdue.map(({ server: s, charge, split, view }) => (
              <li
                key={s.id}
                className="rounded-pv-md border border-white/[0.08] bg-white/[0.02] p-4"
              >
                <div className="flex flex-wrap items-start justify-between gap-3">
                  <div className="min-w-0">
                    <Link
                      href={`/dashboard/servers/${s.id}`}
                      className="font-medium hover:text-pv-brand-light"
                    >
                      {s.hostname}
                    </Link>
                    <p className="mt-0.5 text-xs text-pv-text-faint">
                      {charge.label} · {fmtMoney(charge.totalCents)} for {charge.months} month
                      {charge.months === 1 ? "" : "s"} · expired {fmtDay(s.expiresAt!)}
                    </p>
                  </div>
                  <div className="shrink-0 text-right">
                    {/* `settleOutstanding` quotes the CARD leg, not the full total —
                        wallet credit is applied first — so the button is labelled
                        with the same number it will ask Stripe for. */}
                    {split.cardCents > 0 ? (
                      <>
                        <SettleNowButton serverId={s.id} />
                        <p className="mt-1 text-[11px] text-pv-text-faint">
                          {fmtMoney(split.cardCents)} on your card
                          {split.walletApplied > 0
                            ? `, ${fmtMoney(split.walletApplied)} from your wallet`
                            : ""}
                        </p>
                      </>
                    ) : (
                      <p className="text-xs text-pv-good">
                        Your wallet covers this — it renews automatically within a few minutes.
                      </p>
                    )}
                  </div>
                </div>

                {/* Where they are in the ladder, and what happens next. */}
                <div className="mt-3 border-t border-white/[0.06] pt-3 text-xs">
                  {view.inDunning ? (
                    <p className="text-pv-text-muted">
                      <span className="font-medium text-pv-warn">
                        Attempt {view.attemptsMade} of {view.attemptsTotal} declined.
                      </span>{" "}
                      {view.exhausted
                        ? "That was the last automatic attempt."
                        : `We'll try again automatically ${
                            view.attemptsLeft === 1
                              ? "one more time"
                              : `${view.attemptsLeft} more times`
                          }${view.nextAttemptAt ? `, next on ${fmtDay(view.nextAttemptAt)}` : ""}.`}{" "}
                      {view.suspendAt ? (
                        <>
                          {s.hostname} keeps running until{" "}
                          <span className="font-medium text-pv-text">{fmtDay(view.suspendAt)}</span>,
                          when it pauses if the balance is still unpaid. Nothing is deleted then.
                        </>
                      ) : (
                        <>Automatic suspension is currently switched off on this account.</>
                      )}
                    </p>
                  ) : (
                    <p className="text-pv-text-muted">
                      {cardOnFile ? (
                        <>
                          The next sweep will charge {cardLabel ?? "your saved card"} for the
                          shortfall.
                        </>
                      ) : (
                        <>No card on file, so nothing will be charged automatically.</>
                      )}{" "}
                      {view.suspendAt && (
                        <>
                          {s.hostname} pauses on{" "}
                          <span className="font-medium text-pv-text">{fmtDay(view.suspendAt)}</span>{" "}
                          if it is still unpaid.
                        </>
                      )}
                    </p>
                  )}
                </div>
              </li>
            ))}
          </ul>

          {cardOnFile && (
            <p className="mt-4 text-xs text-pv-text-faint">
              After a renewal fails we retry your card on day{RETRY_DAYS.length === 1 ? "" : "s"}{" "}
              {retryDayList} past expiry — {retryAttempts} attempt
              {retryAttempts === 1 ? "" : "s"}, each with an email — and only pause the
              server on day {CARD_SUSPEND_DAY}, a full day after the final notice.
            </p>
          )}
        </Surface>
      )}

      {suspendedUnpaid.length > 0 && (
        <Surface className="border-pv-warn/30 !bg-pv-warn/[0.06] p-5">
          <StatusPill tone="warn">Paused for non-payment</StatusPill>
          <p className="mt-2 text-sm text-pv-text-muted">
            {suspendedUnpaid.map((s) => s.hostname).join(", ")}{" "}
            {suspendedUnpaid.length === 1 ? "is" : "are"} paused, and the automatic renewal sweep no
            longer picks {suspendedUnpaid.length === 1 ? "it" : "them"} up. Top up your wallet and
            use <span className="font-medium text-pv-text">Renew now</span> on the server to bring{" "}
            {suspendedUnpaid.length === 1 ? "it" : "them"} back — your data is still there.
          </p>
          <div className="mt-3 flex flex-wrap gap-2">
            {suspendedUnpaid.map((s) => (
              <Link key={s.id} href={`/dashboard/servers/${s.id}`} className="btn-secondary py-1.5">
                {s.hostname}
              </Link>
            ))}
          </div>
        </Surface>
      )}

      {/* Cockpit: balance, spend rate + next charge, and a balance-health gauge.
          Sits above the tabs, on every tab, mirroring the mockup's DOM order. */}
      <Surface elevated className="grid items-center gap-6 p-6 sm:grid-cols-[1fr_1fr_auto]">
        <div>
          <p className="mb-1.5 flex items-center gap-1.5 text-[11.5px] text-pv-text-faint">
            <IconWallet width={13} height={13} /> Wallet balance
          </p>
          <p className="font-pv-display text-[26px] font-bold leading-none text-pv-text">
            {fmtMoney(user.balanceCents)}
          </p>
          <p className={`mt-1.5 text-[11.5px] ${daysOfRunway !== null ? "text-pv-good" : "text-pv-text-faint"}`}>
            {daysOfRunway !== null
              ? `Covers ~${daysOfRunway} day${daysOfRunway === 1 ? "" : "s"} at current spend`
              : "No recurring spend yet"}
          </p>
        </div>
        <div>
          <p className="mb-1.5 flex items-center gap-1.5 text-[11.5px] text-pv-text-faint">
            <IconChart width={13} height={13} /> Spend rate
          </p>
          <p className="font-pv-display text-[26px] font-bold leading-none text-pv-text">
            {fmtMoney(monthlySpendCents)}
            <span className="text-sm font-normal text-pv-text-faint">/mo</span>
          </p>
          <p className="mt-1.5 text-[11.5px] text-pv-text-faint">
            {paidServers.length} paid server{paidServers.length === 1 ? "" : "s"} ·{" "}
            {nextRenewal
              ? `next ${fmtDay(nextRenewal.server.expiresAt!)} · ${fmtMoney(nextRenewal.charge.totalCents)}`
              : "no upcoming renewals"}
          </p>
        </div>
        <div className="flex justify-center">
          <Gauge value={balanceCoveragePct} />
        </div>
      </Surface>

      {/* Tabs — same server-rendered ?tab= pattern as Settings. */}
      <div className="flex flex-wrap gap-1 border-b border-white/10">
        {TABS.map((t) => (
          <Link
            key={t.id}
            href={tabHref(t.id)}
            className={`-mb-px rounded-t-lg border-b-2 px-4 py-2 text-sm font-medium transition ${
              tab === t.id
                ? "border-brand-500 text-white"
                : "border-transparent text-slate-400 hover:text-slate-200"
            }`}
          >
            {t.label}
          </Link>
        ))}
      </div>

      {tab === "overview" && (
        <>
          <Surface className="relative overflow-hidden p-6">
            <div
              className="pointer-events-none absolute inset-0"
              style={{
                background:
                  "linear-gradient(120deg, rgb(59 130 246 / 0.12), rgb(111 71 245 / 0.14) 55%, transparent)",
              }}
            />
            <div className="relative flex flex-wrap items-end justify-between gap-6">
              <div>
                <p className="section-label">Add funds</p>
                <p className="mt-2 text-xs text-pv-text-faint">
                  Servers renew and domains register straight from your wallet balance.
                </p>
              </div>
              <AddFunds />
            </div>
            {SANDBOX && (
              <div className="relative mt-5">
                <SandboxTopUp />
              </div>
            )}
            {/* Promo codes are only honored by the demo (non-Stripe) top-up path,
                which reads the coupon cookie in `topUp`. With Stripe configured,
                card checkout never redeems the code, so we hide the field to avoid
                promising a bonus that won't be credited. */}
            {!stripeConfigured() && (
              <div className="relative mt-5 border-t border-white/[0.06] pt-4">
                <CouponField />
              </div>
            )}
          </Surface>

          <div className="grid gap-4 lg:grid-cols-2">
            <Surface className="p-5">
              <p className="section-label mb-3">Upcoming renewals</p>
              {upcoming.length === 0 ? (
                <>
                  <p className="text-sm text-pv-text-muted">
                    Nothing is due. Renewals appear here once you have a paid server, with the exact
                    amount and the date it comes out.
                  </p>
                  <Link href="/dashboard/deploy" className="btn-secondary mt-3 py-1.5">
                    Deploy a server
                  </Link>
                </>
              ) : (
                <ul className="divide-y divide-white/[0.05]">
                  {upcoming.map(({ server: s, charge }) => (
                    <li key={s.id} className="flex items-center gap-3 py-3 text-sm first:pt-0 last:pb-0">
                      <IconTile tone="violet" size={30}>
                        <IconServers width={14} height={14} />
                      </IconTile>
                      <div className="min-w-0 flex-1">
                        <Link
                          href={`/dashboard/servers/${s.id}`}
                          className="block truncate font-medium hover:text-pv-brand-light"
                        >
                          {s.hostname}
                        </Link>
                        {/* The term is named because the figure beside it is a TERM
                            total, not a monthly one — an annual server renews at
                            twelve months in one charge. */}
                        <p className="mt-0.5 text-[11px] text-pv-text-faint">
                          {charge.months === 1 ? "1 month" : `${charge.months} months`} ·{" "}
                          {fmtDay(s.expiresAt!)}
                        </p>
                      </div>
                      <span className="shrink-0 font-mono text-xs text-pv-text-muted">
                        {fmtMoney(charge.totalCents)}
                      </span>
                    </li>
                  ))}
                </ul>
              )}
            </Surface>

            <Surface className="p-5">
              <p className="section-label mb-3">Quick links</p>
              <ul className="divide-y divide-white/[0.05]">
                <li className="flex items-center justify-between gap-3 py-3 text-sm first:pt-0">
                  <div>
                    <p className="font-medium">Refer a friend, earn credit</p>
                    <p className="mt-0.5 text-[11.5px] text-pv-text-faint">
                      You both get wallet credit when they make their first payment.
                    </p>
                  </div>
                  <Link href="/dashboard/refer" className="shrink-0 text-xs font-semibold text-pv-brand-light">
                    Get link →
                  </Link>
                </li>
                <li className="flex items-center justify-between gap-3 py-3 text-sm last:pb-0">
                  <p className="font-medium">View &amp; download all invoices</p>
                  <Link href="/dashboard/invoices" className="shrink-0 text-xs font-semibold text-pv-brand-light">
                    Export →
                  </Link>
                </li>
              </ul>
            </Surface>
          </div>

          <Surface className="p-5">
            <p className="section-label mb-3">Redeem a code</p>
            <RedeemGift />
          </Surface>
        </>
      )}

      {tab === "payment" && (
        <>
          {/* Card on file. This is the instrument worker/billing.ts auto-charges;
              the wallet in the cockpit above is what it funds. */}
          <Surface className="p-5">
            <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
              <p className="section-label flex items-center gap-2">
                <IconTile tone="violet" size={28}><IconWallet width={14} height={14} /></IconTile>
                Payment method
              </p>
              {cardOnFile && (
                <div className="flex flex-wrap items-center gap-2">
                  {cardDeclined && <Pill tone="bad">last charge declined</Pill>}
                  {cardExpired && <Pill tone="bad">expired</Pill>}
                  {cardExpiringSoon && <Pill tone="warn">expires soon</Pill>}
                  {!cardDeclined && !cardExpired && !cardExpiringSoon && <Pill tone="good">active</Pill>}
                </div>
              )}
            </div>

            {!stripeConfigured() ? (
              <p className="text-sm text-pv-text-muted">
                Card payments aren&apos;t configured on this installation, so there is nothing to save
                here yet. Renewals come out of your wallet balance — keep it topped up on the Overview
                tab.
              </p>
            ) : cardOnFile ? (
              <>
                <div className="flex flex-wrap items-center justify-between gap-4">
                  <div className="flex items-center gap-3">
                    <div className="flex h-9 w-14 items-center justify-center rounded-pv-sm border border-white/10 bg-white/[0.04] text-[10px] font-semibold uppercase tracking-wide text-pv-text-muted">
                      {brandLabel(user.cardBrand).slice(0, 6)}
                    </div>
                    <div>
                      <p className="font-medium">{cardLabel}</p>
                      <p className="mt-0.5 text-xs text-pv-text-faint">
                        Charged automatically for renewals your wallet doesn&apos;t cover.
                      </p>
                    </div>
                  </div>
                  {!isImpersonating && <RemoveCardButton label={cardLabel ?? "this card"} />}
                </div>

                {/* Honest states. Each of these changes what will actually happen to
                    the customer's servers, so none of them is left to be inferred
                    from a pill alone. */}
                {cardDeclined && (
                  <p className="mt-4 rounded-pv-md border border-pv-bad/30 bg-pv-bad/[0.06] px-3 py-2.5 text-xs text-pv-text-muted">
                    <span className="font-medium text-pv-bad">This card was declined.</span> The
                    renewal it was for is listed at the top of this page, with the retry schedule and
                    the date the server would pause. If your bank blocked it, paying the balance
                    directly clears the whole sequence.
                  </p>
                )}
                {cardExpired && (
                  <p className="mt-4 rounded-pv-md border border-pv-bad/30 bg-pv-bad/[0.06] px-3 py-2.5 text-xs text-pv-text-muted">
                    <span className="font-medium text-pv-bad">This card has expired.</span> Renewals
                    will fail until you replace it. Adding a new card replaces this one.
                  </p>
                )}
                {cardExpiringSoon && cardExpiry && (
                  <p className="mt-4 rounded-pv-md border border-pv-warn/30 bg-pv-warn/[0.06] px-3 py-2.5 text-xs text-pv-text-muted">
                    <span className="font-medium text-pv-warn">Expiring soon.</span> This card stops
                    working after {String(user.cardExpMonth).padStart(2, "0")}/{user.cardExpYear}. Add a
                    replacement before then and renewals carry on uninterrupted.
                  </p>
                )}

                {!isImpersonating && (
                  <div className="mt-4 border-t border-white/[0.06] pt-4">
                    <AddCardButton label="Replace card" className="btn-secondary py-1.5" />
                    <p className="mt-2 flex items-start gap-1.5 text-xs text-pv-text-faint">
                      <IconShieldCheck width={13} height={13} className="mt-0.5 shrink-0" />
                      Card details are entered on Stripe&apos;s own secure page — Nxeon never sees or
                      stores your card number. Only the brand, last four digits and expiry are kept, to
                      show you which card is on file.
                    </p>
                  </div>
                )}
              </>
            ) : (
              <>
                <p className="text-sm text-pv-text-muted">
                  No card on file. Renewals can only be paid from your wallet balance
                  {autoSuspend ? (
                    <>
                      , and a server whose renewal goes unpaid pauses {graceDays} day
                      {graceDays === 1 ? "" : "s"} past its expiry date.
                    </>
                  ) : (
                    "."
                  )}
                </p>
                <p className="mt-2 text-sm text-pv-text-muted">
                  With a card saved we charge it for whatever your wallet doesn&apos;t cover, and if it
                  fails we retry it {retryAttempts} time{retryAttempts === 1 ? "" : "s"} over{" "}
                  {LAST_RETRY_DAY} days — emailing you each time — before anything is paused.
                </p>
                {!isImpersonating && (
                  <div className="mt-4">
                    <AddCardButton />
                    <p className="mt-2 flex items-start gap-1.5 text-xs text-pv-text-faint">
                      <IconShieldCheck width={13} height={13} className="mt-0.5 shrink-0" />
                      Card details are entered on Stripe&apos;s own secure page — Nxeon never sees or
                      stores your card number. No charge is made when you save a card.
                    </p>
                  </div>
                )}
              </>
            )}

            {isImpersonating && (
              <p className="mt-4 rounded-pv-md border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-xs text-pv-text-faint">
                Card management is disabled while impersonating a customer.
              </p>
            )}
          </Surface>

          <Surface className="p-5">
            <p className="section-label mb-3">Auto-recharge</p>
            {cardOnFile ? (
              <AutoRecharge
                enabled={user.autoRechargeEnabled}
                thresholdCents={user.autoRechargeThresholdCents}
                amountCents={user.autoRechargeAmountCents}
              />
            ) : (
              // The sweep only considers accounts with a saved card, so offering the
              // form without one would take a preference we could never act on.
              <p className="text-sm text-pv-text-muted">
                Keep your wallet topped up automatically. Save a card above and this turns on —
                we&apos;ll top the wallet back up whenever it drops below the amount you choose.
              </p>
            )}
          </Surface>

          <Surface className="p-5">
            <p className="section-label mb-3">Billing details</p>
            <BillingProfile country={user.billingCountry} vatId={user.vatId} />
          </Surface>
        </>
      )}

      {tab === "spend" && (
        <Surface className="p-5">
          <p className="section-label mb-3">Spend controls</p>
          <SpendControls
            budgetEnabled={user.budgetAlertEnabled}
            monthlyBudgetCents={user.monthlyBudgetCents}
            capEnabled={user.spendCapEnabled}
            hardCapCents={user.hardCapCents}
            spentThisMonthCents={spentThisMonthCents}
          />
        </Surface>
      )}

      {tab === "transactions" && (
        <>
          <Surface className="overflow-x-auto p-0">
            <p className="section-label px-5 pt-5">Transactions</p>
            {transactions.length === 0 ? (
              <p className="px-5 py-8 text-sm text-pv-text-muted">
                No transactions yet — your invoices and top-ups will appear here.
              </p>
            ) : (
              <table className="table-shell mt-2 min-w-[520px]">
                <thead>
                  <tr>
                    <th>Description</th>
                    <th className="text-right">Amount</th>
                    <th className="text-right">Date</th>
                  </tr>
                </thead>
                <tbody>
                  {transactions.map((t) => (
                    <tr key={t.id}>
                      <td>{t.description}</td>
                      <td
                        className={`text-right font-mono ${
                          t.amountCents < 0 ? "text-pv-bad" : "text-pv-good"
                        }`}
                      >
                        {t.amountCents < 0 ? "−" : "+"}
                        {fmtMoney(Math.abs(t.amountCents))}
                      </td>
                      <td className="text-right text-pv-text-faint" title={t.createdAt.toISOString()}>
                        {timeAgo(t.createdAt)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </Surface>

          {/* Bandwidth usage */}
          <Surface className="p-5">
            <div className="mb-4 flex flex-wrap items-end justify-between gap-3">
              <div>
                <p className="section-label">Bandwidth usage</p>
                <p className="mt-1 text-sm text-pv-text-muted">
                  Measured transfer per server versus the plan&apos;s {BW_PERIOD_DAYS}-day allowance.
                </p>
              </div>
              <div className="text-right">
                {bwMeasured ? (
                  <>
                    <p className={`text-lg font-bold ${pctTone(totalPct)}`}>
                      {fmtBytes(totalUsedBytes)}
                      <span className="text-sm font-normal text-pv-text-faint">
                        {" "}
                        / {totalAllowanceBytes > 0 ? fmtBytes(totalAllowanceBytes) : "—"}
                      </span>
                    </p>
                    <p className="text-xs text-pv-text-faint">
                      {totalPct.toFixed(0)}% of total allowance{bwPartial ? " so far" : ""}
                    </p>
                  </>
                ) : (
                  <>
                    <p className="text-lg font-bold text-pv-text-faint">
                      —
                      <span className="text-sm font-normal text-pv-text-faint">
                        {" "}
                        / {totalAllowanceBytes > 0 ? fmtBytes(totalAllowanceBytes) : "—"}
                      </span>
                    </p>
                    <p className="text-xs text-pv-text-faint">not measured yet</p>
                  </>
                )}
              </div>
            </div>

            {/* Say what the number is worth BEFORE showing it. A partial period read
                as a full month is the same defect as a figure that was never
                measured at all: both look authoritative and neither is. */}
            {!bwMeasured ? (
              <div className="mb-4 rounded-pv-md border border-white/[0.06] bg-white/[0.02] p-3.5 text-xs text-pv-text-muted">
                <p className="text-sm font-medium text-pv-text">No measurement yet</p>
                <p className="mt-1">
                  Transfer is sampled from the hypervisor every few minutes. Nothing has been recorded
                  yet, so we&apos;re showing no usage figure rather than a zero we can&apos;t stand
                  behind. Your plan allowance below is unchanged
                  {SANDBOX
                    ? ". This is the sandbox — the servers here aren't real, so there is no traffic to meter."
                    : ", and metering starts on its own — nothing for you to do."}
                </p>
              </div>
            ) : (
              <div className="mb-4 space-y-1.5 text-xs">
                {bwPartial && (
                  <p className="text-pv-text-muted">
                    <span className="font-medium text-pv-text">Partial period.</span> Metering has
                    been running since {fmtBwDate(bwHealth.startedAt!)} and these totals only cover the
                    time measured so far — read them as a floor, not as a full {BW_PERIOD_DAYS}-day
                    total.
                  </p>
                )}
                {!bwHealth.live && (
                  <p className="text-pv-warn">
                    Metering last reported {fmtBwSpan(bwHealth.ageMs ?? 0)} ago, so these figures may be
                    behind. Recent transfer is missing rather than counted.
                  </p>
                )}
                {bwGap && bwHealth.gapAt && (
                  <p className="text-pv-warn">
                    Metering was interrupted on {fmtBwDate(bwHealth.gapAt)} — transfer during that
                    outage isn&apos;t included, so this period under-reports.
                  </p>
                )}
              </div>
            )}

            {bandwidth.length === 0 ? (
              <div>
                <p className="text-sm text-pv-text-muted">
                  No active servers, so there is no transfer to meter yet. Deploy one and its usage
                  shows up here within a few minutes.
                </p>
                <Link href="/dashboard/deploy" className="btn-secondary mt-3 py-1.5">
                  Deploy a server
                </Link>
              </div>
            ) : (
              <ul className="space-y-4">
                {bandwidth.map(({ server: s, view }) => {
                  const pct = view.pct ?? 0;
                  return (
                    <li key={s.id}>
                      <div className="mb-1.5 flex items-center justify-between gap-3 text-sm">
                        <Link
                          href={`/dashboard/servers/${s.id}`}
                          className="min-w-0 flex-1 truncate font-medium hover:text-pv-brand-light"
                        >
                          {s.hostname}
                          <span className="ml-2 text-xs font-normal text-pv-text-faint">{s.plan.name}</span>
                        </Link>
                        <span
                          className={`shrink-0 font-mono text-xs ${
                            view.measured ? pctTone(pct) : "text-pv-text-faint"
                          }`}
                        >
                          {view.measured ? fmtBytes(view.usedBytes) : "—"} /{" "}
                          {fmtBytes(view.allowanceBytes)}
                        </span>
                      </div>
                      {view.measured ? (
                        <BarMeter value={view.usedBytes} max={view.allowanceBytes} tone={pct > 80 ? "warn" : "brand"} />
                      ) : (
                        /* No bar at all: an empty meter reads as "you've used
                           nothing", which is a claim we cannot make. */
                        <div className="h-1.5 w-full rounded-full border border-dashed border-white/[0.10]" />
                      )}
                      <p className="mt-1 text-xs text-pv-text-faint">
                        {view.measured && view.measuredFrom ? (
                          <>
                            Measured since {fmtBwDate(view.measuredFrom)} ·{" "}
                            {view.partial
                              ? `${fmtBwSpan(view.coveredMs)} of ${BW_PERIOD_DAYS} days`
                              : `full ${BW_PERIOD_DAYS}-day period`}
                          </>
                        ) : (
                          <>Awaiting the first sample</>
                        )}
                        {s.status !== "RUNNING" && <> · not accruing while {s.status.toLowerCase()}</>}
                      </p>
                      {view.measured && pct > 100 && (
                        <p className="mt-1 text-xs text-pv-bad">
                          Over allowance by {fmtBytes(view.usedBytes - view.allowanceBytes)} — overage
                          may apply.
                        </p>
                      )}
                      {view.measured && pct > 80 && pct <= 100 && (
                        <p className="mt-1 text-xs text-pv-warn">
                          {pct.toFixed(0)}% of allowance used
                          {view.partial ? ` in the ${fmtBwSpan(view.coveredMs)} measured so far` : ""} —
                          approaching your plan limit.
                        </p>
                      )}
                    </li>
                  );
                })}
              </ul>
            )}
          </Surface>

          {/* Invoices */}
          <Surface className="p-0">
            <div className="flex items-center justify-between gap-3 px-5 pt-5">
              <div>
                <p className="section-label">Invoices</p>
                <p className="mt-1 text-xs text-pv-text-faint">Your most recent billing documents.</p>
              </div>
              <Link href="/dashboard/invoices" className="btn-secondary py-1.5">
                View all
              </Link>
            </div>
            {invoices.length === 0 ? (
              <p className="px-5 py-8 text-sm text-pv-text-muted">
                No invoices yet — they appear here once issued for paid services.
              </p>
            ) : (
              <div className="overflow-x-auto pt-3">
                <table className="table-shell min-w-[560px]">
                  <thead>
                    <tr>
                      <th>Number</th>
                      <th>Description</th>
                      <th>Status</th>
                      <th className="text-right">Amount</th>
                      <th className="text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {invoices.map((inv) => (
                      <tr key={inv.id}>
                        <td className="font-mono text-xs text-pv-text-muted">
                          {/* Same formatter as the invoice detail page, the download and
                              the emailed copy. A customer must see one identifier for one
                              invoice, not `#00012` here and `INV-00012` everywhere else. */}
                          <Link href={`/dashboard/invoices/${inv.id}`} className="hover:text-pv-brand-light">
                            {formatInvoiceNumber(inv.number, invoiceNumberPrefix)}
                          </Link>
                        </td>
                        <td className="max-w-xs truncate">
                          <Link href={`/dashboard/invoices/${inv.id}`} className="hover:text-pv-brand-light">
                            {inv.description}
                          </Link>
                        </td>
                        <td>
                          <InvoiceStatusBadge status={inv.status} />
                        </td>
                        <td className="text-right font-mono">{fmtMoney(inv.amountCents)}</td>
                        <td className="text-right">
                          <DownloadInvoiceButton id={inv.id} label="Download" className="btn-ghost py-1 text-xs" />
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </Surface>
        </>
      )}
    </div>
  );
}
